import sys

MINOR = {"a", "an", "and", "as", "at", "but", "by", "for", "in", "nor", "of", "on", "or", "the", "to"}


def headline(line):
    out = []
    for word in line.split():
        stripped_word = word.strip('.,;:!?')
        if stripped_word.lower() in MINOR:
            if out and out[-1] != "":
                out.append(stripped_word.lower())
            else:
                out.append(stripped_word.lower().capitalize())
        else:
            out.append(stripped_word.title())
    return " ".join(out)


def main():
    for line in sys.stdin:
        print(headline(line))


if __name__ == "__main__":
    main()
